<script setup>
import AdminNavigation from '@/Components/Admin/AdminNavigation.vue';import InputError from '@/Components/InputError.vue';import PortalLayout from '@/Layouts/PortalLayout.vue';import{Head,Link,router,useForm}from'@inertiajs/vue3';import{reactive,ref}from'vue';
const props=defineProps({staff:Object,filters:Object,roles:Array});const filter=reactive({search:props.filters.search||'',role:props.filters.role||'',status:props.filters.status||''});const editing=ref(null);const open=ref(false);const form=useForm({name:'',email:'',role:'support',status:'active',password:'',password_confirmation:''});const apply=()=>router.get(route('admin.staff.index'),filter,{preserveState:true,replace:true});const create=()=>{editing.value=null;form.reset();form.role='support';form.status='active';form.clearErrors();open.value=true};const edit=user=>{editing.value=user;Object.assign(form,{name:user.name,email:user.email,role:user.roles[0]?.name||'support',status:user.status,password:'',password_confirmation:''});form.clearErrors();open.value=true};const close=()=>{open.value=false;editing.value=null};const save=()=>{const options={preserveScroll:true,onSuccess:close};editing.value?form.put(route('admin.staff.update',editing.value.public_id),options):form.post(route('admin.staff.store'),options)};const title=value=>value.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
</script>
<template><Head title="Staff management"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="staff"/></template><div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="text-sm font-bold uppercase text-cyan-700">Access control</p><h1 class="mt-1 text-3xl font-bold">Staff management</h1><p class="mt-2 text-slate-600">Manage employee accounts, roles and access status.</p></div><button class="form-button" @click="create">New staff member</button></div><p v-if="$page.props.flash.success" class="success-message mt-5">{{ $page.props.flash.success }}</p><form class="mt-6 grid gap-3 rounded-2xl border border-slate-200 bg-white p-4 shadow-sm md:grid-cols-4" @submit.prevent="apply"><input v-model="filter.search" placeholder="Search name or email"/><select v-model="filter.role"><option value="">All roles</option><option v-for="role in roles" :key="role" :value="role">{{ title(role) }}</option></select><select v-model="filter.status"><option value="">All statuses</option><option value="active">Active</option><option value="suspended">Suspended</option></select><button class="form-button !py-2">Filter</button></form><div class="mt-6 overflow-x-auto rounded-2xl border border-slate-200 bg-white shadow-sm"><table class="w-full min-w-[760px] text-left"><thead class="border-b bg-slate-50 text-xs font-bold uppercase text-slate-500"><tr><th class="px-5 py-3">Staff member</th><th class="px-5 py-3">Role</th><th class="px-5 py-3">Status</th><th class="px-5 py-3">Last updated</th><th class="px-5 py-3 text-right">Action</th></tr></thead><tbody><tr v-for="user in staff.data" :key="user.public_id" class="border-b last:border-0"><td class="px-5 py-4"><strong class="text-[#0B3D6E]">{{ user.name }}</strong><p class="text-sm text-slate-500">{{ user.email }}</p></td><td class="px-5 py-4 text-sm font-semibold">{{ title(user.roles[0]?.name||'Unassigned') }}</td><td class="px-5 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-bold uppercase" :class="user.status==='active'?'bg-emerald-100 text-emerald-700':'bg-amber-100 text-amber-700'">{{ user.status }}</span></td><td class="px-5 py-4 text-sm text-slate-500">{{ new Date(user.updated_at).toLocaleDateString() }}</td><td class="px-5 py-4 text-right"><button class="rounded-lg border px-4 py-2 text-sm font-bold" @click="edit(user)">Edit</button></td></tr><tr v-if="!staff.data.length"><td colspan="5" class="p-10 text-center text-slate-500">No staff match these filters.</td></tr></tbody></table></div><nav v-if="staff.last_page>1" class="mt-5 flex gap-2"><Link v-for="link in staff.links" :key="link.label" :href="link.url||'#'" class="rounded-lg border px-3 py-2 text-sm" :class="[link.active?'bg-[#0B3D6E] text-white':'',!link.url?'pointer-events-none opacity-40':'']" v-html="link.label"/></nav><div v-if="open" class="fixed inset-0 z-50 grid place-items-center overflow-y-auto bg-slate-950/50 p-4" role="dialog" aria-modal="true" @click.self="close"><form class="my-8 w-full max-w-2xl rounded-2xl bg-white p-6 shadow-2xl" @submit.prevent="save"><div class="flex justify-between"><h2 class="text-xl font-bold">{{ editing?'Edit staff member':'New staff member' }}</h2><button type="button" @click="close">&times;</button></div><div class="mt-5 grid gap-5 sm:grid-cols-2"><label>Name<input v-model="form.name" required/><InputError :message="form.errors.name"/></label><label>Email<input v-model="form.email" type="email" required/><InputError :message="form.errors.email"/></label><label>Role<select v-model="form.role" required><option v-for="role in roles" :key="role" :value="role">{{ title(role) }}</option></select><InputError :message="form.errors.role"/></label><label>Status<select v-model="form.status" required><option value="active">Active</option><option value="suspended">Suspended</option></select><InputError :message="form.errors.status"/></label><label>Password <small v-if="editing" class="font-normal text-slate-500">(leave blank to keep current)</small><input v-model="form.password" type="password" :required="!editing"/><InputError :message="form.errors.password"/></label><label>Confirm password<input v-model="form.password_confirmation" type="password" :required="!editing"/></label></div><div class="mt-6 flex justify-end gap-3"><button type="button" class="rounded-xl border px-5 py-3 font-bold" @click="close">Cancel</button><button class="form-button" :disabled="form.processing">Save staff member</button></div></form></div></PortalLayout></template>
